import{parseLocalTraceSegment}from"#tracing/local/trace-reader.js";const TRACE_ID=/^[0-9a-f]{32}$/u,SPAN_ID=/^[0-9a-f]{16}$/u,SEGMENT_FILE=/^[0-9a-f]{16}\.otlp\.json$/u;async function readTraceSources(e,t){let n=await t.getSandbox(),r=`/traces/${e}/segments`,i=await n.run({command:`ls -1 ${r}`});if(i.exitCode!==0)throw Error(`Could not list local trace segments: ${i.stderr}`);let a=i.stdout.split(/\r?\n/u).filter(e=>SEGMENT_FILE.test(e)).sort((e,t)=>e.localeCompare(t));if(a.length>500)throw Error(`Trace has ${a.length} segments (maximum 500).`);let o=[];for(let i of a){if(t.abortSignal.aborted)throw Error(`Trace inspection was cancelled.`);let a=await n.readTextFile({path:`${r}/${i}`});if(!(a===null||a.length>8388608))for(let t of parseLocalTraceSegment(a,e))o.push({segmentFile:i,span:t})}return o}function boundedText(e,t){return e.length<=t?e:`${e.slice(0,t-1)}…`}function detailFields(e){return{arguments:e.span.attributes[`gen_ai.tool.call.arguments`],error:e.span.statusMessage,result:e.span.attributes[`gen_ai.tool.call.result`]}}export{SPAN_ID,TRACE_ID,boundedText,detailFields,readTraceSources};